import java.util.*;

class Solution {
    public List<List<String>> partition(String s) {
        int n = s.length();
        List<List<String>> result = new ArrayList<>();
        int total = 1 << (n - 1);

        for (int mask = 0; mask < total; mask++) {
            List<String> path = new ArrayList<>();
            int start = 0;
            boolean ok = true;
            for (int i = 0; i < n - 1; i++) {
                if ((mask & (1 << i)) != 0) {
                    if (!isPalindrome(s, start, i)) {
                        ok = false;
                        break;
                    }
                    path.add(s.substring(start, i + 1));
                    start = i + 1;
                }
            }
            if (ok && isPalindrome(s, start, n - 1)) {
                path.add(s.substring(start));
                result.add(path);
            }
        }
        return result;
    }

    private boolean isPalindrome(String s, int lo, int hi) {
        while (lo < hi) {
            if (s.charAt(lo) != s.charAt(hi)) return false;
            lo++;
            hi--;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    private String s;
    private List<List<String>> result;
    private List<String> path;

    public List<List<String>> partition(String s) {
        this.s = s;
        this.result = new ArrayList<>();
        this.path = new ArrayList<>();
        dfs(0);
        return result;
    }

    private void dfs(int start) {
        if (start == s.length()) {
            result.add(new ArrayList<>(path));   // 必须拷贝
            return;
        }
        for (int end = start; end < s.length(); end++) {
            if (!isPalindrome(start, end)) continue;
            path.add(s.substring(start, end + 1));
            dfs(end + 1);
            path.remove(path.size() - 1);        // 撤销
        }
    }

    private boolean isPalindrome(int lo, int hi) {
        while (lo < hi) {
            if (s.charAt(lo) != s.charAt(hi)) return false;
            lo++;
            hi--;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    private String s;
    private boolean[][] pal;
    private List<List<String>> result;
    private List<String> path;

    public List<List<String>> partition(String s) {
        this.s = s;
        int n = s.length();
        this.pal = new boolean[n][n];

        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                if (s.charAt(i) == s.charAt(j) && (j - i < 2 || pal[i + 1][j - 1])) {
                    pal[i][j] = true;
                }
            }
        }

        this.result = new ArrayList<>();
        this.path = new ArrayList<>();
        dfs(0);
        return result;
    }

    private void dfs(int start) {
        if (start == s.length()) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int end = start; end < s.length(); end++) {
            if (!pal[start][end]) continue;
            path.add(s.substring(start, end + 1));
            dfs(end + 1);
            path.remove(path.size() - 1);
        }
    }
}
